/**
 * Synthetic fleet registry (public/data/fleet.json) and real harbour locations
 * (public/data/harbours.json). Generated by scripts/generate-fleet.mjs; nothing here is a
 * CFIS record. The runtime simulation (domain/simulation.ts) animates trips and hails.
 */
export type Coast = 'atlantic' | 'pacific'
/** DFO administrative regions. */
export type DfoRegion = 'NL' | 'MAR' | 'GLF' | 'QC' | 'PAC' | 'ARC'
export type Gear =
  | 'Bottom trawl'
  | 'Midwater trawl'
  | 'Longline'
  | 'Gillnet'
  | 'Trap'
  | 'Purse seine'
  | 'Dredge'
  | 'Handline'
  | 'Troll'
export type Zone = 'offshore' | 'inshore'
export type LonLat = [number, number]

export interface Harbour {
  id: string
  name: string
  province: string
  region: DfoRegion
  coast: Coast
  lon: number
  lat: number
  /** A point on open water 1–4 km off the harbour mouth; first/last point of every trip. */
  approach: LonLat
  /** Larger fishing harbours, labelled on the overview map. */
  major: boolean
}

export interface FleetVessel {
  id: string
  /** Canadian Fishing Vessel number (synthetic, 6 digits). */
  cfv: string
  name: string
  lengthM: number
  gear: Gear
  species: string
  region: DfoRegion
  coast: Coast
  homePort: string
  /** Licences held by the vessel's licence holder (synthetic). */
  licences: number
  zone: Zone
  /** Fishing position, on water. */
  ground: { lon: number; lat: number; area: string }
  /** Harbour approach → ground, every point and segment on water. */
  route: LonLat[]
  /** 0..1 offset into the trip cycle, so the fleet is spread over all phases at t = 0. */
  phase: number
  /** Trip cycle length in demo seconds (scaled, not real time). */
  cycle: number
}

export interface FleetFile {
  generated: string
  seed: number
  note: string
  licences: {
    total: number
    byRegion: Record<DfoRegion, number>
    bySpecies: Record<string, number>
  }
  vessels: FleetVessel[]
}

export interface HarbourFile {
  source: string
  license: string
  harbours: Harbour[]
}
